      "source": "食材与过敏原知识.md",
      "text": "| 过敏原 | 常见食物来源 | 说明 |\n|---|---|---|\n| 花生 | 宫保鸡丁、花生酱、花生油、沙茶酱 | 最凶险的过敏原之一，可能引发严重过敏反应 |\n| 坚果 | 腰果、核桃、杏仁、松子 | 常出现在甜点、沙拉、炒菜中 |\n| 海鲜（鱼） | 各种鱼类、鱼露、鱼高汤 | 鱼类过敏常伴随海鲜类交叉反应 |\n| 甲壳类 | 虾、蟹、龙虾、贝类 | 冬阴功、寿司、海鲜料理常见 |\n| 乳制品 | 牛奶、奶酪、黄油、奶油 | 西式酱汁、甜点、奶茶常见 |\n| 麸质 | 小麦、大麦、黑麦、面筋 | 面食、面包、酱油、啤酒常见 |\n| 蛋 | 鸡蛋、蛋黄酱、蛋糕、裹粉 | 白切鸡可能含蛋、炸物裹粉常含蛋 |\n| 大豆 | 豆腐、酱油、豆豉、味噌、豆浆 | 亚洲菜几乎无处不在 |\n\n**注意**：过敏原信息来自菜单识别与知识库，可能有遗漏。涉及过敏原时，AI 助手必须提示用户「建议向服务员确认」，不得给出诊断性结论。",
