      "source": "食材与过敏原知识.md",
      "text": "| 食材 | 特性 | 常见搭配 | 注意事项 |\n|---|---|---|---|\n| 三黄鸡 | 肉质嫩、脂肪适中 | 白切、炖汤、焖 | 鸡肉过敏者避免 |\n| 海斑鱼 | 肉质紧实、少刺、鲜甜 | 清蒸、红烧 | 海鲜过敏者避免 |\n| 五花肉 | 肥瘦相间、油脂香 | 蒜泥白肉、红烧肉 | 高血脂者适量 |\n| 嫩豆腐 | 嫩滑、易碎、豆香 | 麻婆豆腐、味噌汤 | 大豆过敏者避免 |\n| 河粉 | 爽滑、吸味、易糊 | 干炒、汤粉 | 麸质敏感者注意 |\n| 虾 | 弹牙、鲜甜 | 冬阴功、白灼、寿司 | 甲壳类过敏者避免 |\n| 香茅 | 柠檬香、清新 | 冬阴功、咖喱 | 无常见过敏 |\n| 豆豉 | 咸香、发酵味 | 蒸排骨、炒菜 | 大豆过敏者避免 |",
