      "id": "食材与过敏原知识#731",
      "title": "口味与辣度分级说明",
      "source": "食材与过敏原知识.md",
      "text": "| 辣度等级 | 数值范围 | 代表菜品 | 说明 |\n|---|---|---|---|\n| 不辣 | 0 | 白切鸡、清蒸鱼、番茄炒蛋 | 完全无辣，适合清淡口味 |\n| 微辣 | 0.1-0.3 | 干炒牛河、蒜蓉时蔬 | 只有隐约辣味 |\n| 中辣 | 0.4-0.6 | 宫保鸡丁、蒜泥白肉 | 明显辣味，大多数可接受 |\n| 重辣 | 0.7-1.0 | 麻婆豆腐、水煮鱼、冬阴功 | 麻辣厚重，重口味爱好者 |",
      "keywords": []
