      "title": "常见问答补充",
      "source": "食材与过敏原知识.md",
      "text": "**「寿司里的芥末算辣吗？」**\n算。芥末的辣来自异硫氰酸酯，与辣椒素不同，刺激鼻腔而非舌头，且挥发快、不持久。\n\n**「味噌汤是素食吗？」**\n不一定。传统味噌汤用鲣鱼高汤（dashi）打底，严格素食者需点「昆布高汤」版本。\n\n**「冬阴功能不能不加虾？」**\n可以。可要求换成鸡肉或纯菌菇版，酸辣底味不变，但虾的鲜甜会减弱。\n\n**「干炒牛河和湿炒牛河有什么区别？」**\n干炒不带汁、河粉根根分明、锅气足；湿炒带芡汁、口感滑。干炒更考验师傅火候。\n\n**「可乐鸡翅的甜味是糖还是可乐？」**\n两者都有。可乐本身含糖，收汁后糖分浓缩，所以热量比看上去高。\n\n**「为什么粤菜馆的清蒸鱼比红烧鱼贵？」**\n清蒸对鱼的鲜度要求最高，不新鲜的鱼无法用重味掩盖，所以选料成本更高。",
